package de.unibremen.marsmod.world;

import de.unibremen.marsmod.MarsMod;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.biome.Biome;

/** Keys of the biomes defined in data/marsmod/worldgen/biome/ (generated by tools/worldgen). */
public final class ModBiomes {
    public static final ResourceKey<Biome> ERODED_BADLANDS = key("eroded_badlands");

    private static ResourceKey<Biome> key(String name) {
        return ResourceKey.create(Registries.BIOME, Identifier.fromNamespaceAndPath(MarsMod.MODID, name));
    }

    private ModBiomes() {
    }
}
